<script setup>
import {reactive,computed} from 'vue';import {checkLessonAnswer} from '../practice';
const props=defineProps({lesson:Object,mastered:Boolean});const emit=defineEmits(['mastered']);
const questions=computed(()=>props.lesson.foundation.practice);
const state=reactive({answers:['','',''],choices:[-1,-1,-1],passed:[false,false,false],feedback:['','',''],revealed:[false,false,false]});
function check(i){const q=questions.value[i];let ok=false;if(q.kind==='choice'){ok=state.choices[i]===q.answer;}else{try{const value=JSON.parse(state.answers[i]);ok=checkLessonAnswer(q,value,props.lesson.codeKey);}catch{state.passed[i]=false;state.feedback[i]='请使用JSON格式：数字直接写，真假写true/false，数组用方括号；字符串需要双引号。';return;}}state.passed[i]=ok;state.feedback[i]=(ok?'正确。':'这次还没有对上。')+q.explanation;if(state.passed.every(Boolean))emit('mastered',props.lesson.id);}
function changed(i){state.passed[i]=false;state.feedback[i]='';}
const answer=q=>q.kind==='choice'?`${'ABC'[q.answer]} · ${q.options[q.answer]}`:JSON.stringify(q.answer);
</script>
<template><section class="lesson-practice" id="lesson-practice" aria-label="本节三道练习"><div class="practice-header"><div><span class="eyebrow">CHECK YOUR UNDERSTANDING</span><h2>先巩固，再推演，最后应用</h2></div><span class="practice-saved" v-if="mastered">✓ 本节练习已通过</span></div><p>这三题只使用本节及此前讲过的知识。先独立尝试，再查看反馈；本节首次全部答对后会保存通过状态。</p><article v-for="(q,i) in questions" :key="lesson.id+'-'+i" class="mini-question" :class="{passed:state.passed[i]}"><span class="eyebrow">{{['01 / 基础巩固','02 / 逐步推演','03 / 场景应用'][i]}}</span><h3>{{q.question}}</h3><div v-if="q.kind==='choice'" class="mini-options"><button v-for="(option,j) in q.options" :key="j" :aria-pressed="state.choices[i]===j" :class="{selected:state.choices[i]===j}" @click="state.choices[i]=j;changed(i)"><b>{{'ABC'[j]}}</b><span>{{option}}</span></button></div><label v-else class="mini-output">你的答案（JSON）<textarea v-model="state.answers[i]" :aria-label="`本节第${i+1}题答案`" @input="changed(i)" placeholder="例如：3、true、[1,2,3]，请按题目要求填写一种。"></textarea></label><div class="mini-actions"><button class="primary" @click="check(i)" :disabled="q.kind==='choice'&&state.choices[i]<0">{{state.passed[i]?'✓ 已答对':'检查答案'}}</button><button @click="state.revealed[i]=!state.revealed[i]">{{state.revealed[i]?'收起思路与答案':'查看思路与答案'}}</button></div><p class="mini-feedback" aria-live="polite">{{state.feedback[i]}}</p><div v-if="state.revealed[i]" class="mini-solution"><p><strong>参考答案：</strong><code>{{answer(q)}}</code></p><p>{{q.explanation}}</p><p class="micro">看懂后可收起答案，换一组输入再自己解释一次。查看答案不会自动记录为通过。</p></div></article></section></template>
